import{_ as n,l as s,o as e,c as i,v as r,p as l,x as t,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"标记清除与分代","description":"","frontmatter":{"title":"标记清除与分代","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gc-mark-gen.md","filePath":"cs/gc-mark-gen.md","lastUpdated":1789023840000}'),p={name:"cs/gc-mark-gen.md"};function E(m,a,B,A,_,f){const o=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="标记清除与分代" tabindex="-1">标记清除与分代 <a class="header-anchor" href="#标记清除与分代" aria-label="Permalink to &quot;标记清除与分代&quot;">​</a></h1><div class="epigraph"><p>追踪式回收先从根标记可达，再清未标记或把活对象搬到新半区；分代假设新对象早死，平时只扫幼代，老到老代靠写屏障记录跨代指针。</p><footer>—— 据 McCarthy, 1960；Ungar, Generation Scavenging, 1984；Jones, Hosking and Moss, The Garbage Collection Handbook 整理</footer></div><p>上一课<a href="/cs/runtime-gc">运行时与 GC 直觉</a>给出堆、根、可达即活，并点名标记-清扫、复制、分代。本课不重定义根。缺口是三种算法怎么走完、碎片与写屏障各自补哪块洞。异常表下一课才处理非局部跳出；本课仍停在堆。操作系统课从内核门再问虚拟内存从哪来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标记-清扫：着色（三色抽象）从灰根推进，黑为活，白为死；再扫堆把白链进空闲表。碎片：反复清扫留下洞，分配要找合适块或整理。复制式：from/to 半区，活对象 bump 到 to，指针更新，from 整区丢弃——自动压缩，空间折半。缺口是在直觉之后把步骤钉死，不是再解释 <code>malloc</code>。</p><p>分代：幼代用复制（小、回收勤），活过几次晋升老代；老代少扫。跨代指针：老对象指向新对象时，幼代回收必须把该指针当额外根。写屏障：每次堆写检查并记入 remembered set。无屏障会漏标或错收。</p><h3 id="写屏障不是内存模型的-fence" tabindex="-1">写屏障不是内存模型的 fence <a class="header-anchor" href="#写屏障不是内存模型的-fence" aria-label="Permalink to &quot;写屏障不是内存模型的 fence&quot;">​</a></h3><p><a href="/cs/memory-consistency">内存一致性</a> 的屏障管可见性。GC 写屏障是编译器插入的「记一笔跨代」，可以很弱（卡片标记）。不要把 MESI 请进来。</p><p><span class="marginnote">McCarthy 标记回收。Ungar 1984 分代清扫。Jones 等手册分章。Dijkstra 等三色不变式点名：并发 GC 靠屏障维持，本课以 STW 为默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配：空闲链表或 bump。STW 标记-清扫或复制。分代：分配进幼代；满则幼代复制，晋升阈值按年龄。编译器在指针写处插屏障（分代/增量才必须）。</p>',11)),(e(),l(h,null,{default:t(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%22%5D%20--%3E%20MARK%5B%22%E4%B8%89%E8%89%B2%E6%A0%87%E8%AE%B0%22%5D%0A%20%20MARK%20--%3E%20SW%5B%22%E6%B8%85%E6%89%AB%E7%A9%BA%E9%97%B2%E8%A1%A8%22%5D%0A%20%20MARK%20--%3E%20COPY%5B%22%E5%A4%8D%E5%88%B6%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20COPY%20--%3E%20GEN%5B%22%E5%B9%BC%E4%BB%A3%E5%8B%A4%E6%89%AB%20%2F%20%E6%99%8B%E5%8D%87%22%5D%0A%20%20GEN%20--%3E%20WB%5B%22%E5%86%99%E5%B1%8F%E9%9A%9C%E8%AE%B0%E8%B7%A8%E4%BB%A3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p><a href="/cs/bfs-unweighted">图遍历</a> 在堆图上；指针识别仍须编译器合作（栈图 vs 保守）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>暂停时间：全堆标记随活对象涨；分代把常见暂停压到幼代。吞吐：屏障与复制搬迁的代价。实时性仍不保证，本课不写 Metronome。循环引用：追踪式可收；引用计数要单独处理，点名不展开。</p><p>不要在无根登记的情况下把指针藏进非指针位型。安全点：GC 只在可枚举寄存器的位置切入。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内核分配器、不写页表。并发漏标只点三色。后课默认：分代 + 写屏障是托管语言的常见实现。非局部控制（throw）要沿栈拆帧并调析构，对象仍须可枚举——下一课异常表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>标记-清扫留碎片；复制压缩但半区。</li><li>分代依赖早死假设与写屏障。</li><li>STW 默认；并发是屏障加强。</li><li>出处：McCarthy, 1960；Ungar, 1984；Jones, Hosking and Moss。</li></ul>',8))])}const b=n(p,[["render",E]]);export{g as __pageData,b as default};
